from collections import Counter, deque

def transform(grid):
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The key is a vertical run of source colors in the lower-left, with
    # the corresponding replacement color immediately to its right.
    runs = []
    for c in range(min(6, w - 1)):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            runs.append((r - start, c, start, r))
    if not runs:
        return out

    length, kc, r0, r1 = max(runs, key=lambda x: (x[0], -x[1], x[3]))
    if length < 2:
        return out
    key_cells = {(r, c) for r in range(r0, r1) for c in (kc, kc + 1)}
    mappings = [(grid[r][kc], grid[r][kc + 1]) for r in range(r0, r1)]

    # Find monochromatic components outside the key.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in key_cells or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and
                            (ny, nx) not in key_cells and
                            (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            comp = {
                "color": color,
                "cells": cells,
                "r0": min(rs), "r1": max(rs),
                "c0": min(cs), "c1": max(cs),
                "orient": None
            }
            if (len(cells) == 3 and comp["r1"] - comp["r0"] == 1
                    and comp["c1"] - comp["c0"] == 1):
                missing = next((y, x)
                               for y in range(comp["r0"], comp["r1"] + 1)
                               for x in range(comp["c0"], comp["c1"] + 1)
                               if (y, x) not in cells)
                comp["orient"] = (
                    missing[0] - comp["r0"],
                    missing[1] - comp["c0"]
                )
            components.append(comp)

    # Complementary L-shaped objects of the same color define a filled
    # rectangle. Background-colored mappings act as cutouts when enclosed.
    positive, cutouts = [], []
    for source, target in mappings:
        pieces = [p for p in components
                  if p["color"] == source and p["orient"] is not None]
        for i in range(len(pieces)):
            for j in range(i + 1, len(pieces)):
                a, b = pieces[i], pieces[j]
                if (a["orient"][0] + b["orient"][0] != 1 or
                        a["orient"][1] + b["orient"][1] != 1):
                    continue
                if a["r0"] == b["r0"] or a["c0"] == b["c0"]:
                    continue
                op = {
                    "target": target,
                    "source": source,
                    "top": min(a["r0"], b["r0"]),
                    "bottom": max(a["r1"], b["r1"]),
                    "left": min(a["c0"], b["c0"]),
                    "right": max(a["c1"], b["c1"]),
                    "motifs": a["cells"] | b["cells"]
                }
                if target == bg:
                    cutouts.append(op)
                else:
                    positive.append(op)

    # Larger regions are painted first, allowing smaller regions to overlay.
    positive.sort(key=lambda op: -(
        (op["bottom"] - op["top"] + 1) *
        (op["right"] - op["left"] + 1)
    ))
    for op in positive:
        for r in range(op["top"], op["bottom"] + 1):
            for c in range(op["left"], op["right"] + 1):
                if (r, c) in op["motifs"]:
                    out[r][c] = original[r][c]
                elif (r, c) not in key_cells:
                    out[r][c] = op["target"]

    # A background mapping cuts out a region only when it lies wholly within
    # a painted region.
    for op in cutouts:
        enclosed = any(
            other["top"] <= op["top"] and other["bottom"] >= op["bottom"] and
            other["left"] <= op["left"] and other["right"] >= op["right"]
            for other in positive
        )
        if not enclosed:
            continue
        for r in range(op["top"], op["bottom"] + 1):
            for c in range(op["left"], op["right"] + 1):
                if (r, c) in op["motifs"]:
                    out[r][c] = original[r][c]
                elif (r, c) not in key_cells:
                    out[r][c] = bg

    # Solid 2x2 monochromatic objects are directly recolored by the key.
    mapping = dict(mappings)
    for comp in components:
        if (len(comp["cells"]) == 4 and
                comp["r1"] - comp["r0"] == 1 and
                comp["c1"] - comp["c0"] == 1 and
                comp["color"] in mapping):
            target = mapping[comp["color"]]
            for r, c in comp["cells"]:
                out[r][c] = target

    return out
